    try std.testing.expectEqual(@as(usize, 4 * 1024 * 1024), pdfImageEmbeddingBatchBytes(4 * 1024 * 1024, 32 * 1024 * 1024));
    try std.testing.expectEqual(@as(usize, 16 * 1024 * 1024), pdfImageEmbeddingBatchBytes(null, 16 * 1024 * 1024));

