fn clearPublishedGeneratedArtifacts(runtime: *EnrichmentRuntime) void {
    var it = runtime.published_generated_artifacts.iterator();
    while (it.next()) |entry| runtime.alloc.free(@constCast(entry.key_ptr.*));
    runtime.published_generated_artifacts.clearAndFree(runtime.alloc);
}

fn clearIsolatedFailedIndexes(runtime: *EnrichmentRuntime) void {
    var it = runtime.isolated_failed_indexes.iterator();
    while (it.next()) |entry| runtime.alloc.free(@constCast(entry.key_ptr.*));
    runtime.isolated_failed_indexes.clearAndFree(runtime.alloc);
    var source_it = runtime.isolated_failed_sources.iterator();
    while (source_it.next()) |entry| runtime.alloc.free(@constCast(entry.key_ptr.*));
    runtime.isolated_failed_sources.clearAndFree(runtime.alloc);
}

fn markIsolatedFailedIndex(runtime: *EnrichmentRuntime, index_name: []const u8) void {
    if (runtime.isolated_failed_indexes.contains(index_name)) return;
    const owned_key = runtime.alloc.dupe(u8, index_name) catch return;
    errdefer runtime.alloc.free(owned_key);
    runtime.isolated_failed_indexes.put(runtime.alloc, owned_key, {}) catch return;
}

fn markIsolatedFailedSource(runtime: *EnrichmentRuntime, index_name: []const u8, artifact_name: []const u8) void {
    if (index_name.len == 0 or artifact_name.len == 0 or index_name.len > std.math.maxInt(u32)) return;
    const key = runtime.alloc.alloc(u8, @sizeOf(u32) + index_name.len + artifact_name.len) catch return;
    errdefer runtime.alloc.free(key);
    std.mem.writeInt(u32, key[0..4], @intCast(index_name.len), .big);
    @memcpy(key[4 .. 4 + index_name.len], index_name);
    @memcpy(key[4 + index_name.len ..], artifact_name);
    if (runtime.isolated_failed_sources.getKey(key) != null) {
        runtime.alloc.free(key);
        return;
    }
    runtime.isolated_failed_sources.put(runtime.alloc, key, {}) catch return;
}

fn isolatedFailedSourceMatches(key: []const u8, index_name: []const u8, artifact_name: []const u8) bool {
    if (key.len < @sizeOf(u32)) return false;
    const index_len: usize = std.mem.readInt(u32, key[0..4], .big);
    if (index_len > key.len - 4) return false;
    return std.mem.eql(u8, key[4 .. 4 + index_len], index_name) and
        std.mem.eql(u8, key[4 + index_len ..], artifact_name);
}

fn generatedArtifactAlreadyPublished(runtime: *EnrichmentRuntime, artifact_key: []const u8) bool {
    return runtime.published_generated_artifacts.contains(artifact_key);
}

fn rememberPublishedGeneratedArtifact(runtime: *EnrichmentRuntime, artifact_key: []const u8) !void {
    if (runtime.published_generated_artifacts.contains(artifact_key)) return;
    const owned_key = try runtime.alloc.dupe(u8, artifact_key);
    errdefer runtime.alloc.free(owned_key);
    try runtime.published_generated_artifacts.put(runtime.alloc, owned_key, {});
}

fn rememberPublishedGeneratedBatch(runtime: *EnrichmentRuntime, batch: derived_types.DerivedBatch) !void {
    for (batch.dense_embeddings) |embedding| {
        if (embedding.artifact_key) |artifact_key| try rememberPublishedGeneratedArtifact(runtime, artifact_key);
    }
    for (batch.sparse_embeddings) |embedding| {
        if (embedding.artifact_key) |artifact_key| try rememberPublishedGeneratedArtifact(runtime, artifact_key);
    }
}

fn checkProviderInvocation(runtime: *EnrichmentRuntime, recovery_key: InferenceRecoveryKey, foreground_bounded: bool) !void {
    lockInferenceRecovery(runtime);
    const circuit_open_until_ns = if (runtime.inference_recovery.get(recovery_key)) |state|
        state.circuit_open_until_ns
    else
        0;
    runtime.inference_recovery_mutex.unlock();
    if (circuit_open_until_ns > platform_time.monotonicNs()) return error.InferenceCircuitOpen;
    const guard = runtime.active_provider_guard;
    if (guard.deadline_ns == null and guard.cancellation.ptr == null) return;
    try guard.check();
    if (!foreground_bounded) return error.UnboundedEnrichmentProvider;
}

const AssetInvocationCancellation = struct {
    lifecycle: CancellationToken,
    request: CancellationToken,
    inherited: CancellationToken,

    fn isCancelled(ptr: *const anyopaque) bool {
        const self: *const @This() = @ptrCast(@alignCast(ptr));
        return self.lifecycle.isCancelled() or self.request.isCancelled() or
            self.inherited.isCancelled();
    }
};

fn scopedAssetProducer(
    runtime: *EnrichmentRuntime,
    producer: asset_producer_mod.Producer,
    cancellation: *AssetInvocationCancellation,
) asset_producer_mod.Producer {
    const guard = runtime.active_provider_guard;
    cancellation.* = .{
        .lifecycle = runtime.config.cancellation,
        .request = guard.cancellation,
        .inherited = producer.invocation_context.cancellation,
    };
    const deadline_ns = if (producer.invocation_context.deadline_ns) |inherited|
        if (guard.deadline_ns) |deadline| @min(inherited, deadline) else inherited
    else
        guard.deadline_ns;
    return producer.withInvocationContext(.{
        .io = producer.invocation_context.io orelse runtime.config.io,
        .deadline_ns = deadline_ns,
        .cancellation = .{
            .ptr = cancellation,
            .is_cancelled_fn = AssetInvocationCancellation.isCancelled,
        },
        .max_response_bytes = producer.invocation_context.max_response_bytes,
        .progress = producer.invocation_context.progress orelse
            inference_request_context.ProgressSink{ .ptr = runtime, .update_fn = noteInferenceProgress },
    });
}

fn checkAssetProviderInvocation(
    runtime: *EnrichmentRuntime,
    producer: asset_producer_mod.Producer,
    alloc: Allocator,
    requests: []const asset_producer_mod.Request,
) !void {
    if (requests.len == 0) return;
    const recovery_key = assetInferenceRecoveryKey(requests[0]);
    lockInferenceRecovery(runtime);
    const circuit_open_until_ns = if (runtime.inference_recovery.get(recovery_key)) |state|
        state.circuit_open_until_ns
    else
        0;
    runtime.inference_recovery_mutex.unlock();
    if (circuit_open_until_ns > platform_time.monotonicNs()) return error.InferenceCircuitOpen;
    const guard = runtime.active_provider_guard;
    if (guard.deadline_ns == null and guard.cancellation.ptr == null) return;
    try guard.check();
    const foreground_bounded = try producer.foregroundBoundedForRequests(alloc, requests);
    // Request-aware routing may parse provider configuration. Recheck before
    // entering the provider so that work done by the contract hook cannot
    // consume the caller's remaining deadline unnoticed.
    try guard.check();
    if (!foreground_bounded)
        return error.UnboundedEnrichmentProvider;
}

fn checkProviderFailureGuard(runtime: *EnrichmentRuntime) !void {
    const guard = runtime.active_provider_guard;
    if (guard.deadline_ns == null and guard.cancellation.ptr == null) return;
    try guard.check();
}

fn assetProviderRequestContext(runtime: *EnrichmentRuntime) inference_request_context.RequestContext {
    const guard = runtime.active_provider_guard;
    const cancellation = if (guard.cancellation.ptr != null)
        guard.cancellation
    else
        runtime.config.cancellation;
    return .{
        .io = if (runtime.io_impl) |io_impl| io_impl.io() else std.Io.Threaded.global_single_threaded.io(),
        .deadline_ns = guard.deadline_ns orelse
            platform_time.monotonicNs() +| @max(runtime.config.sync_wait_timeout_ms, 1) *| std.time.ns_per_ms,
        .cancellation = if (cancellation.ptr != null) cancellation else null,
        .progress = .{ .ptr = runtime, .update_fn = noteInferenceProgress },
    };
}

fn foregroundProviderRequestContext(runtime: *EnrichmentRuntime) ?inference_request_context.RequestContext {
    const guard = runtime.active_provider_guard;
    if (guard.deadline_ns == null and guard.cancellation.ptr == null) return null;
    return assetProviderRequestContext(runtime);
}

fn checkProviderFailureGuardRecording(
    runtime: *EnrichmentRuntime,
    recovery_key: InferenceRecoveryKey,
    batch_items: usize,
) !void {
    checkProviderFailureGuard(runtime) catch |err| {
        noteInferenceControlFailure(runtime, recovery_key, err, batch_items);
        return err;
    };
}

fn assetProducerCanBatchGuarded(
    runtime: *EnrichmentRuntime,
    producer: asset_producer_mod.Producer,
    alloc: Allocator,
    requests: []const asset_producer_mod.Request,
) !bool {
    return try assetProducerBatchModeGuarded(runtime, producer, alloc, requests) != .none;
}

fn assetProducerBatchModeGuarded(
    runtime: *EnrichmentRuntime,
    producer: asset_producer_mod.Producer,
    alloc: Allocator,
    requests: []const asset_producer_mod.Request,
) !inference_work.BatchMode {
    try checkAssetProviderInvocation(runtime, producer, alloc, requests);
    var cancellation: AssetInvocationCancellation = undefined;
    const scoped = scopedAssetProducer(runtime, producer, &cancellation);
    const result = scoped.batchMode(alloc, requests) catch |err| {
        try checkProviderFailureGuard(runtime);
        return err;
    };
    try checkProviderFailureGuard(runtime);
    return result;
}

fn assetProducerProduceGuarded(
    runtime: *EnrichmentRuntime,
    producer: asset_producer_mod.Producer,
    alloc: Allocator,
    request: asset_producer_mod.Request,
) ![]u8 {
    const recovery_key = assetInferenceRecoveryKey(request);
    try checkAssetProviderInvocation(runtime, producer, alloc, &.{request});
    var cancellation: AssetInvocationCancellation = undefined;
    const scoped = scopedAssetProducer(runtime, producer, &cancellation);
    const produced = scoped.produce(alloc, request) catch |err| {
        checkProviderFailureGuardRecording(runtime, recovery_key, 1) catch |guard_err| return guard_err;
        if (inferenceControlFailure(err)) noteInferenceControlFailure(runtime, recovery_key, err, 1);
        return err;
    };
    checkProviderFailureGuardRecording(runtime, recovery_key, 1) catch |err| {
        alloc.free(produced);
        return err;
    };
    noteInferenceControlSuccess(runtime, recovery_key, 1);
    return produced;
}

fn assetProducerProduceBatchGuarded(
    runtime: *EnrichmentRuntime,
    producer: asset_producer_mod.Producer,
    alloc: Allocator,
    requests: []const asset_producer_mod.Request,
) ![][]u8 {
    if (requests.len == 0) return try alloc.alloc([]u8, 0);
    const recovery_key = assetInferenceRecoveryKey(requests[0]);
    try checkAssetProviderInvocation(runtime, producer, alloc, requests);
    var cancellation: AssetInvocationCancellation = undefined;
    const scoped = scopedAssetProducer(runtime, producer, &cancellation);
    const produced = scoped.produceBatch(alloc, requests) catch |err| {
        checkProviderFailureGuardRecording(runtime, recovery_key, requests.len) catch |guard_err| return guard_err;
        if (inferenceControlFailure(err)) noteInferenceControlFailure(runtime, recovery_key, err, requests.len);
        return err;
    };
    checkProviderFailureGuardRecording(runtime, recovery_key, requests.len) catch |err| {
        for (produced) |output| if (output.len > 0) alloc.free(output);
        alloc.free(produced);
        return err;
    };
    noteInferenceControlSuccess(runtime, recovery_key, requests.len);
    return produced;
}

fn assetProducerProduceBatchReportedGuarded(
    runtime: *EnrichmentRuntime,
    producer: asset_producer_mod.Producer,
    alloc: Allocator,
    requests: []const asset_producer_mod.Request,
) !asset_producer_mod.ProducedBatch {
    try checkAssetProviderInvocation(runtime, producer, alloc, requests);
    var cancellation: AssetInvocationCancellation = undefined;
    const scoped = scopedAssetProducer(runtime, producer, &cancellation);
    var produced = scoped.produceBatchReported(alloc, requests) catch |err| {
        try checkProviderFailureGuard(runtime);
        return err;
    };
    checkProviderFailureGuard(runtime) catch |err| {
        produced.deinit(alloc);
        return err;
    };
    return produced;
}

fn assetProducerBorrowedRasterBatchAvailableGuarded(
    runtime: *EnrichmentRuntime,
    producer: asset_producer_mod.Producer,
    alloc: Allocator,
    requests: []const asset_producer_mod.Request,
) !bool {
    const guard = runtime.active_provider_guard;
    try guard.check();
    if ((guard.deadline_ns != null or guard.cancellation.ptr != null) and
        producer.vtable.borrowed_raster_batch_available_with_context == null)
        return error.UnboundedEnrichmentProvider;
    var cancellation: AssetInvocationCancellation = undefined;
    const scoped = scopedAssetProducer(runtime, producer, &cancellation);
    const available = scoped.borrowedRasterBatchAvailable(alloc, requests) catch |err| {
        try checkProviderFailureGuard(runtime);
        return err;
    };
    try checkProviderFailureGuard(runtime);
    return available;
}

fn assetProducerProduceBorrowedRasterBatchReportedGuarded(
    runtime: *EnrichmentRuntime,
    producer: asset_producer_mod.Producer,
    alloc: Allocator,
    requests: []const asset_producer_mod.Request,
    rasters: []const antfly_image.BorrowedRasterAttachment,
) !asset_producer_mod.ProducedBatch {
    const guard = runtime.active_provider_guard;
    try guard.check();
    if ((guard.deadline_ns != null or guard.cancellation.ptr != null) and
        producer.vtable.produce_borrowed_raster_batch_reported_with_context == null)
        return error.UnboundedEnrichmentProvider;
    var cancellation: AssetInvocationCancellation = undefined;
    const scoped = scopedAssetProducer(runtime, producer, &cancellation);
    var produced = scoped.produceBorrowedRasterBatchReported(alloc, requests, rasters) catch |err| {
        try checkProviderFailureGuard(runtime);
        return err;
    };
    checkProviderFailureGuard(runtime) catch |err| {
        produced.deinit(alloc);
        return err;
    };
    return produced;
}

fn embedDenseWithRetry(
    dense_embedder: embedder_mod.DenseEmbedder,
    runtime: *EnrichmentRuntime,
    embedding_name: []const u8,
    text: []const u8,
    dims: u32,
) ![]f32 {
    const recovery_key = denseInferenceRecoveryKey(dense_embedder, embedding_name);
    var attempt: u32 = 0;
    while (true) : (attempt += 1) {
        try checkProviderInvocation(runtime, recovery_key, dense_embedder.foreground_bounded);
        const vector = (if (foregroundProviderRequestContext(runtime)) |context|
            dense_embedder.embedDenseWithContext(runtime.alloc, embedding_name, text, dims, context)
        else
            dense_embedder.embedDense(runtime.alloc, embedding_name, text, dims)) catch |err| {
            try checkProviderFailureGuardRecording(runtime, recovery_key, 1);
            if (inferenceControlFailure(err)) {
                noteInferenceControlFailure(runtime, recovery_key, err, 1);
                return err;
            }
            if (!isRetryableEnrichmentError(err)) return err;
            switch (transientEmbedRetryDecision(runtime, attempt)) {
                .retry_inline => {},
                .yield_to_worker => return err,
                .abort_shutdown => return error.EnrichmentRetryAborted,
            }
            if (attempt == 0) noteTransientEmbedRetry(runtime, err);
            sleepRetryBackoff(transientEmbedRetrySleepNs(attempt));
            continue;
        };
        checkProviderFailureGuardRecording(runtime, recovery_key, 1) catch |err| {
            runtime.alloc.free(vector);
            return err;
        };
        noteInferenceControlSuccess(runtime, recovery_key, 1);
        return vector;
    }
}

fn embedDenseBatchWithRetry(
    dense_embedder: embedder_mod.DenseEmbedder,
    runtime: *EnrichmentRuntime,
    embedding_name: []const u8,
    texts: []const []const u8,
    dims: u32,
) ![]const []const f32 {
    const recovery_key = denseInferenceRecoveryKey(dense_embedder, embedding_name);
    var attempt: u32 = 0;
    while (true) : (attempt += 1) {
        try checkProviderInvocation(runtime, recovery_key, dense_embedder.foreground_bounded);
        const vectors = (if (foregroundProviderRequestContext(runtime)) |context|
            dense_embedder.embedDenseBatchWithContext(runtime.alloc, embedding_name, texts, dims, context)
        else
            dense_embedder.embedDenseBatch(runtime.alloc, embedding_name, texts, dims)) catch |err| {
            try checkProviderFailureGuardRecording(runtime, recovery_key, texts.len);
            if (inferenceControlFailure(err)) {
                noteInferenceControlFailure(runtime, recovery_key, err, texts.len);
                return err;
            }
            if (!isRetryableEnrichmentError(err)) return err;
            switch (transientEmbedRetryDecision(runtime, attempt)) {
                .retry_inline => {},
                .yield_to_worker => return err,
                .abort_shutdown => return error.EnrichmentRetryAborted,
            }
            if (attempt == 0) noteTransientEmbedRetry(runtime, err);
            sleepRetryBackoff(transientEmbedRetrySleepNs(attempt));
            continue;
        };
        checkProviderFailureGuardRecording(runtime, recovery_key, texts.len) catch |err| {
            embedder_mod.freeDenseEmbeddingBatch(runtime.alloc, vectors);
            return err;
        };
        noteInferenceControlSuccess(runtime, recovery_key, texts.len);
        return vectors;
    }
}

