test "asset batch fallback isolates malformed envelope and preserves typed mixed results" {
    const alloc = std.testing.allocator;

    const FallbackProducer = struct {
        batch_count: usize = 0,
        single_count: usize = 0,

        fn producer(self: *@This()) asset_producer_mod.Producer {
            return .{
                .ptr = self,
                .vtable = &.{
                    .produce = produce,
                    .produce_batch = produceBatch,
                    .invocation_memory_for_requests = testInvocationMemoryForRequests,
                },
            };
        }

        fn produce(ptr: *anyopaque, a: Allocator, request: asset_producer_mod.Request) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.single_count += 1;
            return try std.fmt.allocPrint(a, "ok:{s}", .{request.source_text});
        }

        fn produceBatch(ptr: *anyopaque, a: Allocator, _: []const asset_producer_mod.Request) ![][]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.batch_count += 1;
            const malformed = try a.alloc([]u8, 1);
            errdefer a.free(malformed);
            malformed[0] = try a.dupe(u8, "orphaned-output");
            return malformed;
        }
    };

    const MixedResultProducer = struct {
        batch_count: usize = 0,
        single_count: usize = 0,
        retryable: bool = false,

        fn producer(self: *@This()) asset_producer_mod.Producer {
            return .{
                .ptr = self,
                .vtable = &.{
                    .produce = produce,
                    .produce_batch_reported = produceBatchReported,
                    .invocation_memory_for_requests = testInvocationMemoryForRequests,
                },
            };
        }

        fn produce(ptr: *anyopaque, _: Allocator, _: asset_producer_mod.Request) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.single_count += 1;
            return error.TestUnexpectedSequentialFallback;
        }

        fn produceBatchReported(ptr: *anyopaque, a: Allocator, requests: []const asset_producer_mod.Request) !asset_producer_mod.ProducedBatch {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.batch_count += 1;
            const produced = try a.alloc(asset_producer_mod.ProducedItem, requests.len);
            errdefer a.free(produced);
            produced[0] = .{
                .identity = .{},
                .result = .{ .value = try a.dupe(u8, "native:three") },
            };
            produced[1] = .{
                .identity = .{},
                .result = .{ .item_error = .{
                    .cause = if (self.retryable) error.EmbedRateLimited else error.UnsupportedGeneratorProvider,
                    .code = .invalid_request,
                    .retryable = self.retryable,
                } },
            };
            return .{
                .items = produced,
                .execution = inference_work.ExecutionReport.native(requests.len),
            };
        }
    };

    const TestItem = struct {
        fn make(a: Allocator, doc_key: []const u8, source: []const u8, artifact_key: []const u8, state_key: []const u8) !AssetProducerBatchItem {
            return .{
                .request = .{
                    .kind = .asset,
                    .index_name = "asset_idx",
                    .artifact_name = "asset",
                    .doc_key = doc_key,
                    .source_field = "body",
                    .content_type = "text/plain",
                },
                .producer_type = .generator,
                .config_json = try a.dupe(u8, "{\"provider\":\"test\"}"),
                .raw_doc = try a.dupe(u8, "{}"),
                .source_text = try a.dupe(u8, source),
                .artifact_key = try a.dupe(u8, artifact_key),
                .state_key = try a.dupe(u8, state_key),
                .state_value = try a.dupe(u8, "{\"state\":\"done\"}"),
            };
        }
    };

    var backend = mem_backend.Backend.init(alloc, .{});
    defer backend.close();
    var store = try backend.runtimeStore(alloc, .{ .name = "docs" });
    defer store.deinit();
    var erased_store = try backend_erased.storeFrom(alloc, store);
    defer erased_store.deinit();

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var path_buf: [std.fs.max_path_bytes]u8 = undefined;
    const index_path = try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/indexes", .{tmp.sub_path});
    var index_manager = try index_manager_mod.IndexManager.init(alloc, index_path);
    defer index_manager.deinit();

    var fake = FallbackProducer{};
    const producer = fake.producer();
    var runtime = EnrichmentRuntime{
        .alloc = alloc,
        .io_impl = null,
        .store = erased_store,
        .owns_store = false,
        .change_journal = undefined,
        .replay_source = undefined,
        .index_manager = &index_manager,
        .write_ctx = undefined,
        .write_fn = undefined,
        .notify_ctx = undefined,
        .notify_fn = undefined,
        .config = .{ .asset_producer = producer },
        .ownership = undefined,
    };

    var items = std.ArrayListUnmanaged(AssetProducerBatchItem).empty;
    defer {
        clearAssetProducerBatchItems(alloc, &items);
        items.deinit(alloc);
    }
    try items.append(alloc, try TestItem.make(alloc, "doc:1", "one", "artifact:one", "state:one"));
    try items.append(alloc, try TestItem.make(alloc, "doc:2", "two", "artifact:two", "state:two"));

    var window = GeneratedReplayWindow{ .alloc = alloc };
    defer window.deinit();

    try flushAssetProducerBatch(&runtime, &items, &window);

    try std.testing.expectEqual(@as(usize, 1), fake.batch_count);
    try std.testing.expectEqual(@as(usize, 2), fake.single_count);
    try std.testing.expectEqual(@as(usize, 2), window.changed_artifact_keys.items.len);

    const first = try storeGetAlloc(&runtime, "artifact:one");
    defer alloc.free(first);
    try std.testing.expectEqualStrings("ok:one", first);
    const second = try storeGetAlloc(&runtime, "artifact:two");
    defer alloc.free(second);
    try std.testing.expectEqualStrings("ok:two", second);

    // A valid typed envelope is authoritative. Preserve its successful item
    // and deterministic failure independently; never discard the success and
    // rerun the whole partition through singleton callbacks.
    var mixed = MixedResultProducer{};
    var failure_capture = TestFailureCapture{};
    runtime.config.asset_producer = mixed.producer();
    runtime.failure_ctx = &failure_capture;
    runtime.failure_fn = TestFailureCapture.record;
    defer clearIsolatedFailedIndexes(&runtime);
    try items.append(alloc, try TestItem.make(alloc, "doc:3", "three", "artifact:three", "state:three"));
    try items.append(alloc, try TestItem.make(alloc, "doc:4", "four", "artifact:four", "state:four"));
    try flushAssetProducerBatch(&runtime, &items, &window);

    try std.testing.expectEqual(@as(usize, 1), mixed.batch_count);
    try std.testing.expectEqual(@as(usize, 0), mixed.single_count);
    try std.testing.expectEqual(@as(usize, 1), failure_capture.count);
    const third = try storeGetAlloc(&runtime, "artifact:three");
    defer alloc.free(third);
    try std.testing.expectEqualStrings("native:three", third);
    try std.testing.expectError(error.NotFound, storeGetAlloc(&runtime, "artifact:four"));

    mixed.retryable = true;
    runtime.config.worker_retry_max_attempts = 2;
    try items.append(alloc, try TestItem.make(alloc, "doc:5", "five", "artifact:five", "state:five"));
    try items.append(alloc, try TestItem.make(alloc, "doc:6", "six", "artifact:six", "state:six"));
    const failed_identity = requestFailureFingerprint(items.items[1].request);
    try std.testing.expectError(error.EmbedRateLimited, flushAssetProducerBatch(&runtime, &items, &window));
    const fifth = try storeGetAlloc(&runtime, "artifact:five");
    defer alloc.free(fifth);
    try std.testing.expectEqualStrings("native:three", fifth);
    try std.testing.expectEqual(failed_identity, runtime.active_failure_fingerprint);

    // Replaying an exhausted item must park that item, not throw a batch-owned
    // error at the supervisor and fail the whole enrichment worker.
    runtime.retry_failure_fingerprint = failed_identity;
    runtime.retry_failure_count = 1;
    try items.append(alloc, try TestItem.make(alloc, "doc:5", "five", "artifact:five", "state:five"));
    try items.append(alloc, try TestItem.make(alloc, "doc:6", "six", "artifact:six", "state:six"));
    try flushAssetProducerBatch(&runtime, &items, &window);
    try std.testing.expectEqual(@as(usize, 2), failure_capture.count);
    try std.testing.expectEqual(@as(usize, 0), mixed.single_count);
}

test "asset preparation is lazy and byte bounded across retryable provider batches" {
    const alloc = std.testing.allocator;
    const Harness = struct {
        calls: usize = 0,
        publications: u64 = 0,

        fn produce(ptr: *anyopaque, a: Allocator, request: asset_producer_mod.Request) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.calls += 1;
            if (std.mem.eql(u8, request.source_text, "blocked")) return error.EmbedRateLimited;
            return try a.dupe(u8, "generated");
        }
        fn canBatch(_: *anyopaque, _: Allocator, _: []const asset_producer_mod.Request) !bool {
            return false;
        }
        fn write(
            ptr: *anyopaque,
            _: derived_types.DerivedBatch,
            _: []const GeneratedArtifactPromotion,
            _: []const []const u8,
            _: ?GeneratedWriteFence,
        ) !GeneratedRecordCommit {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.publications += 1;
            return .{ .sequence = self.publications };
        }
        fn notify(_: *anyopaque, _: u64) void {}
        fn item(a: Allocator, request: enrichment_types.GeneratedEnrichmentRequest, source: []const u8) !AssetProducerBatchItem {
            return .{
                .request = request,
                .producer_type = .generator,
                .config_json = try a.dupe(u8, "{}"),
                .raw_doc = try a.dupe(u8, "{\"body\":\"large retained document\"}"),
                .source_text = try a.dupe(u8, source),
                .source_parts_json = try a.dupe(u8, "[]"),
                .artifact_key = try a.dupe(u8, request.doc_key),
                .state_key = try std.fmt.allocPrint(a, "state:{s}", .{request.doc_key}),
                .state_value = try a.dupe(u8, "state"),
            };
        }
    };
    var backend = mem_backend.Backend.init(alloc, .{});
    defer backend.close();
    var store = try backend.runtimeStore(alloc, .{ .name = "docs" });
    defer store.deinit();
    var erased_store = try backend_erased.storeFrom(alloc, store);
    defer erased_store.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var path_buf: [std.fs.max_path_bytes]u8 = undefined;
    const index_path = try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/indexes", .{tmp.sub_path});
    var manager = try index_manager_mod.IndexManager.init(alloc, index_path);
    defer manager.deinit();
    var harness = Harness{};
    var runtime = EnrichmentRuntime{
        .alloc = alloc,
        .io_impl = null,
        .store = erased_store,
        .owns_store = false,
        .change_journal = undefined,
        .replay_source = undefined,
        .index_manager = &manager,
        .write_ctx = &harness,
        .write_fn = Harness.write,
        .notify_ctx = &harness,
        .notify_fn = Harness.notify,
        .config = .{ .asset_producer = .{ .ptr = &harness, .vtable = &.{
            .produce = Harness.produce,
            .can_produce_batch = Harness.canBatch,
            .invocation_memory_for_requests = testInvocationMemoryForRequests,
        } }, .inline_retry_max_attempts = 1 },
        .ownership = undefined,
    };
    defer clearPublishedGeneratedArtifacts(&runtime);
    defer clearIsolatedFailedIndexes(&runtime);
    var window = GeneratedReplayWindow{ .alloc = alloc };
    defer window.deinit();
    var queued = std.ArrayListUnmanaged(enrichment_types.GeneratedEnrichmentRequest).empty;
    defer queued.deinit(alloc);
    var prepared_sources = PreparedDocumentSourceCache.init(&runtime);
    defer prepared_sources.deinit();
    const request: enrichment_types.GeneratedEnrichmentRequest = .{
        .kind = .asset,
        .index_name = "asset_idx",
        .artifact_name = "generated",
        .doc_key = "blocked",
        .source_field = "body",
        .producer_json = "{\"type\":\"generator\",\"config\":{\"provider\":\"mock\"}}",
        .execution_json = "{\"batch_items\":8,\"batch_bytes\":1}",
        .sequence = 7,
    };
    // There is deliberately no document in the store. Planning must retain
    // the request, not read/materialize it or invoke the provider.
    try processAssetOrDefer(&runtime, request, &queued, &prepared_sources, &window);
    try std.testing.expectEqual(@as(usize, 1), queued.items.len);
    try std.testing.expectEqual(@as(usize, 0), harness.calls);
    var batch = PreparedAssetBatch{};
    defer batch.deinit(alloc);
    for ([_][]const u8{ "blocked", "healthy-a", "healthy-b" }) |source| {
        var next = request;
        next.doc_key = source;
        const item = try Harness.item(alloc, next, source);
        try std.testing.expect(assetProducerRetainedBytes(item) > assetProducerBatchItemBytes(item));
        try batch.append(&runtime, &window, item);
        try std.testing.expectEqual(@as(usize, 1), batch.items.items.len);
        try batch.flushIfFull(&runtime, &window);
        try std.testing.expectEqual(@as(usize, 0), batch.items.items.len);
        try std.testing.expectEqual(@as(usize, 0), batch.retained_bytes);
    }
    try std.testing.expectEqual(@as(usize, 3), harness.calls);
    try std.testing.expectEqual(@as(u64, 2), harness.publications);
    try std.testing.expectEqual(error.EmbedRateLimited, batch.retry_error.?);
    try std.testing.expectEqual(requestFailureFingerprint(request), batch.retry_fingerprint);
    // Two individually admissible items must flush at the byte boundary even
    // though the item-count limit allows eight. Account for raw/state bytes,
    // not just the much smaller text sent to the provider.
    for ([_][]const u8{ "bounded-a", "bounded-b" }, 0..) |source, i| {
        var next = request;
        next.doc_key = source;
        next.execution_json = "{\"batch_items\":8,\"batch_bytes\":128}";
        const item = try Harness.item(alloc, next, source);
        try std.testing.expect(assetProducerRetainedBytes(item) < 128);
        try std.testing.expect(assetProducerRetainedBytes(item) * 2 > 128);
        try batch.append(&runtime, &window, item);
        try std.testing.expectEqual(@as(usize, 1), batch.items.items.len);
        try std.testing.expectEqual(@as(usize, 3) + i, harness.calls);
        try std.testing.expect(batch.retained_bytes < 128);
    }
    try batch.flush(&runtime, &window);
    try std.testing.expectEqual(@as(usize, 5), harness.calls);
    try std.testing.expectEqual(@as(u64, 4), harness.publications);

    // Serial compatibility must not let a retryable first item starve an
    // independent sibling in the same bounded batch either.
    const blocked = try Harness.item(alloc, request, "blocked");
    defer freeAssetProducerBatchItem(alloc, blocked);
    var healthy_request = request;
    healthy_request.doc_key = "healthy-serial";
    const healthy = try Harness.item(alloc, healthy_request, "healthy");
    defer freeAssetProducerBatchItem(alloc, healthy);
    try std.testing.expectError(error.EmbedRateLimited, flushAssetProducerBatchSequential(&runtime, runtime.config.asset_producer.?, &.{ blocked, healthy }, &window));
    try std.testing.expectEqual(@as(usize, 7), harness.calls);
    try std.testing.expectEqual(requestFailureFingerprint(request), runtime.active_failure_fingerprint);
    runtime.retry_failure_fingerprint = requestFailureFingerprint(request);
    runtime.retry_failure_count = 1;
    try flushGeneratedReplayWindow(&runtime, &window);
    try std.testing.expectEqual(@as(u64, 5), harness.publications);
    try std.testing.expectEqual(requestFailureFingerprint(request), runtime.retry_failure_fingerprint);
    try std.testing.expectEqual(@as(u32, 1), runtime.retry_failure_count);
}

test "asset batch fallback keeps the logical request retry budget" {
    const alloc = std.testing.allocator;

    const AlwaysTransientProducer = struct {
        batch_count: usize = 0,
        single_count: usize = 0,

        fn producer(self: *@This()) asset_producer_mod.Producer {
            return .{
                .ptr = self,
                .vtable = &.{
                    .produce = produce,
                    .produce_batch = produceBatch,
                    .invocation_memory_for_requests = testInvocationMemoryForRequests,
                },
            };
        }

        fn produce(ptr: *anyopaque, _: Allocator, _: asset_producer_mod.Request) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.single_count += 1;
            return error.EmbedRateLimited;
        }

        fn produceBatch(ptr: *anyopaque, _: Allocator, _: []const asset_producer_mod.Request) ![][]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.batch_count += 1;
            return error.EmbedRateLimited;
        }
    };

    const TestItem = struct {
        fn make(a: Allocator) !AssetProducerBatchItem {
            return .{
                .request = .{
                    .kind = .asset,
                    .index_name = "asset_idx",
                    .artifact_name = "generated_v1",
                    .doc_key = "doc:1",
                    .source_field = "body",
                    .content_type = "text/plain",
                    .sequence = 7,
                },
                .producer_type = .generator,
                .config_json = try a.dupe(u8, "{\"provider\":\"test\"}"),
                .raw_doc = try a.dupe(u8, "{}"),
                .source_text = try a.dupe(u8, "one"),
                .artifact_key = try a.dupe(u8, "artifact:one"),
                .state_key = try a.dupe(u8, "state:one"),
                .state_value = try a.dupe(u8, "{\"state\":\"done\"}"),
            };
        }
    };

    var backend = mem_backend.Backend.init(alloc, .{});
    defer backend.close();
    var store = try backend.runtimeStore(alloc, .{ .name = "docs" });
    defer store.deinit();
    var erased_store = try backend_erased.storeFrom(alloc, store);
    defer erased_store.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var path_buf: [std.fs.max_path_bytes]u8 = undefined;
    const index_path = try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/asset-retry-indexes", .{tmp.sub_path});
    var index_manager = try index_manager_mod.IndexManager.init(alloc, index_path);
    defer index_manager.deinit();
    var producer_impl = AlwaysTransientProducer{};
    var failure_capture = TestFailureCapture{};
    var runtime = EnrichmentRuntime{
        .alloc = alloc,
        .io_impl = null,
        .store = erased_store,
        .owns_store = false,
        .change_journal = undefined,
        .replay_source = undefined,
        .index_manager = &index_manager,
        .write_ctx = undefined,
        .write_fn = undefined,
        .failure_ctx = &failure_capture,
        .failure_fn = TestFailureCapture.record,
        .notify_ctx = undefined,
        .notify_fn = undefined,
        .config = .{
            .asset_producer = producer_impl.producer(),
            .worker_retry_max_attempts = 2,
        },
        .ownership = undefined,
    };
    defer clearIsolatedFailedIndexes(&runtime);
    var window = GeneratedReplayWindow{ .alloc = alloc };
    defer window.deinit();

    var first = std.ArrayListUnmanaged(AssetProducerBatchItem).empty;
    defer first.deinit(alloc);
    try first.append(alloc, try TestItem.make(alloc));
    try std.testing.expectError(error.EmbedRateLimited, flushAssetProducerBatch(&runtime, &first, &window));
    runtime.retry_failure_fingerprint = runtime.active_failure_fingerprint;
    runtime.consecutive_retry_count = 1;
    runtime.retry_failure_count = 1;
    runtime.retrying = true;

    var second = std.ArrayListUnmanaged(AssetProducerBatchItem).empty;
    defer second.deinit(alloc);
    try second.append(alloc, try TestItem.make(alloc));
    try flushAssetProducerBatch(&runtime, &second, &window);

    try std.testing.expectEqual(@as(usize, 2), producer_impl.batch_count);
    try std.testing.expectEqual(@as(usize, 2), producer_impl.single_count);
    try std.testing.expectEqual(@as(usize, 1), failure_capture.count);
    try std.testing.expectEqual(@as(u64, 2), failure_capture.failure.?.attempts);
}

test "document extraction generated OCR bypasses unsupported native batch" {
    const alloc = std.testing.allocator;

    const FallbackProducer = struct {
        batch_count: usize = 0,
        single_count: usize = 0,

        fn producer(self: *@This()) asset_producer_mod.Producer {
            return .{
                .ptr = self,
                .vtable = &.{
                    .produce = produce,
                    .produce_batch = produceBatch,
                    .can_produce_batch = canProduceBatch,
                    .invocation_memory_for_requests = invocationMemory,
                },
            };
        }

        fn invocationMemory(
            _: *anyopaque,
            _: Allocator,
            requests: []const asset_producer_mod.Request,
        ) !inference_work.InvocationMemoryPlan {
            const result_bytes = std.math.mul(usize, @max(requests.len, 1), 1024) catch
                return error.InferenceEncodedBytesExceeded;
            return .{
                .attachment_transport = .borrowed_binary,
                .fixed_bytes = result_bytes,
                .allocator_limit_bytes = result_bytes,
                .max_result_bytes_per_item = 1024,
                .max_result_bytes = result_bytes,
            };
        }

        fn canProduceBatch(_: *anyopaque, _: Allocator, _: []const asset_producer_mod.Request) !bool {
            return false;
        }

        fn produce(ptr: *anyopaque, a: Allocator, request: asset_producer_mod.Request) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.single_count += 1;
            const parts = request.source_parts_json orelse "";
            if (std.mem.indexOf(u8, parts, "unit:2") != null) return error.BadUnitInput;
            if (std.mem.indexOf(u8, parts, "unit:1") != null) return try a.dupe(u8, "ok:unit:1");
            if (std.mem.indexOf(u8, parts, "unit:3") != null) return try a.dupe(u8, "ok:unit:3");
            return error.BadUnitInput;
        }

        fn produceBatch(ptr: *anyopaque, _: Allocator, _: []const asset_producer_mod.Request) ![][]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.batch_count += 1;
            // Capability admission must prevent this function from running.
            return error.BadUnitInput;
        }
    };

    const TestUnit = struct {
        fn make(a: Allocator, id: []const u8) !document_extraction_mod.Unit {
            return .{
                .unit_id = try a.dupe(u8, id),
                .unit_type = try a.dupe(u8, "image"),
                .text = try a.dupe(u8, "ocr_pending"),
                .method = try a.dupe(u8, "ocr_pending"),
                .extraction_status = try a.dupe(u8, "pending_ocr"),
            };
        }
    };

    var fake = FallbackProducer{};
    const producer = fake.producer();
    var resource_manager = resource_manager_mod.ResourceManager.init(.{});
    defer resource_manager.deinit(alloc);
    var runtime = EnrichmentRuntime{
        .alloc = alloc,
        .io_impl = null,
        .store = undefined,
        .owns_store = false,
        .change_journal = undefined,
        .replay_source = undefined,
        .index_manager = undefined,
        .write_ctx = undefined,
        .write_fn = undefined,
        .notify_ctx = undefined,
        .notify_fn = undefined,
        .config = .{
            .asset_producer = producer,
            .resource_manager = &resource_manager,
        },
        .ownership = undefined,
    };

    var units = [_]document_extraction_mod.Unit{
        try TestUnit.make(alloc, "unit:1"),
        try TestUnit.make(alloc, "unit:2"),
        try TestUnit.make(alloc, "unit:3"),
    };
    defer for (&units) |*unit| unit.deinit(alloc);

    try completeRuntimeDocumentExtractionGeneratedTextBatch(
        &runtime,
        alloc,
        producer,
        .{ .ocr_enabled = true },
        .{ .max_items = 8, .max_bytes = 1024 * 1024 },
        "data:application/pdf;base64,AA==",
        "",
        "ocr",
        "application/pdf",
        units[0..],
        .ocr,
    );

    try std.testing.expectEqual(@as(usize, 0), fake.batch_count);
    try std.testing.expectEqual(@as(usize, 3), fake.single_count);
    try std.testing.expectEqualStrings("ok:unit:1", units[0].text);
    try std.testing.expectEqualStrings("completed", units[0].extraction_status.?);
    try std.testing.expectEqualStrings("", units[1].text);
    try std.testing.expectEqualStrings("failed_ocr", units[1].extraction_status.?);
    try std.testing.expect(units[1].extraction_warning != null);
    try std.testing.expect(std.mem.indexOf(u8, units[1].extraction_warning.?, "BadUnitInput") != null);
    try std.testing.expectEqualStrings("ok:unit:3", units[2].text);
    try std.testing.expectEqualStrings("completed", units[2].extraction_status.?);
}

